import {courseGroups,groupFor,buildHierarchy,folderTrail,folderLabel,searchFolder,learningSort,folderListing} from './hierarchy.mjs';
import {normalize,cleanTitle,isVideo} from './core.mjs';

export function createLibraryView(ctx) {
  const {courses,videos,docs,nodes,esc,icon,fmt,button,courseCard,videoRow,heading,empty,progress}=ctx;
  const index=buildHierarchy(nodes,[...videos,...docs]);
  let category='all',current=null,query='',type='all',status='all',page=1,includeChildren=false;
  const $=s=>document.querySelector(s);
  const url=(c,f=c)=>`#course?id=${encodeURIComponent(c)}&folder=${encodeURIComponent(f)}`;
  const done=e=>e.videos.filter(v=>progress().completed[v.id]).length;
  const groupLink=g=>`#library?group=${g.id}`;
  const countLine=e=>`${fmt(e.videos.length)} video · ${fmt(e.docs.length)} tài liệu`;
  const trailLink=(c,f,label,active=false)=>active?`<span aria-current="page">${esc(label)}</span>`:`<a href="${url(c,f)}">${esc(label)}</a>`;
  function groupCards(){return `<div class="learning-groups">${courseGroups.map((g,i)=>`<a class="learning-group tone-${i}" href="${groupLink(g)}"><span class="group-glyph">${icon(g.icon)}</span><strong>${esc(g.title)}</strong><small>${g.courses.length} khóa học ${icon('arrow')}</small></a>`).join('')}</div>`}
  function homeGroups(){return `<section class="learning-start"><div class="section-title"><div><h2>Bạn muốn học gì hôm nay?</h2><p>Chọn nhóm học → chọn khóa → chọn chương → mở bài.</p></div><a class="text-button" href="#library">Mở thư viện ${icon('arrow')}</a></div>${groupCards()}</section>`}
  function libraryIntro(selected){if(selected!==undefined)category=courseGroups.some(g=>g.id===selected)?selected:'all';return `<div class="catalog-explainer"><span class="row-icon">${icon('route')}</span><div><strong>Thư viện được chia thành 5 hướng học</strong><p>Vào từng khóa để mở chương, chủ đề và tài liệu đi kèm.</p></div></div><div class="category-tabs" aria-label="Nhóm khóa học"><button data-category="all" class="category-tab ${category==='all'?'active':''}" aria-pressed="${category==='all'}">Tất cả <span>${courses.length}</span></button>${courseGroups.map(g=>`<button data-category="${g.id}" class="category-tab ${category===g.id?'active':''}" aria-pressed="${category===g.id}">${icon(g.icon)}${esc(g.title)} <span>${g.courses.length}</span></button>`).join('')}</div>`}
  function groupedCourses(list){const groups=courseGroups.filter(g=>category==='all'||category===g.id);return groups.map((g,i)=>{const cs=g.courses.map(id=>list.find(c=>c.id===id)).filter(Boolean);if(!cs.length)return '';return `<section class="catalog-group"><div class="catalog-group-heading"><span class="group-step">${String(courseGroups.indexOf(g)+1).padStart(2,'0')}</span><div><h2>${esc(g.title)}</h2><p>${esc(g.description)}</p></div><small>${cs.length} khóa học</small></div><div class="course-grid">${cs.map(c=>courseCard(c,c.index)).join('')}</div></section>`}).join('')||empty('Chưa có khóa phù hợp','Thử chọn nhóm khác hoặc xóa từ khóa tìm kiếm.','search')}
  function sideTree(c,folder,trail){const active=new Set(trail.map(n=>n.id));function branch(parent,depth=0){const sub=index.folders.get(parent);return sub.folders.map(f=>`<li><a class="outline-link ${f.id===folder.id?'selected':''}" href="${url(c.id,f.id)}" ${f.id===folder.id?'aria-current="page"':''}><span>${icon(active.has(f.id)?'folder':'chevron')}</span><span>${esc(folderLabel(f))}<small>${countLine(index.folders.get(f.id))}</small></span></a>${active.has(f.id)?`<ul>${branch(f.id,depth+1)}</ul>`:''}</li>`).join('')}
    return `<aside class="course-outline" id="course-outline"><details open><summary>Mục lục khóa học ${icon('book')}</summary><a href="${url(c.id)}" class="outline-root ${folder.id===c.id?'selected':''}">${icon('home')}Tổng quan khóa học</a><ul>${branch(c.id)}</ul></details><a class="outline-drive" href="https://drive.google.com/drive/folders/${c.id}" target="_blank" rel="noopener noreferrer">${icon('external')}Thư mục Google Drive</a></aside>`;
  }
  function folderCard(c,f,i){const e=index.folders.get(f.id),completed=done(e),percent=e.videos.length?Math.round(completed/e.videos.length*100):0;return `<a class="module-card" href="${url(c.id,f.id)}"><div class="module-top"><span class="module-number">${String(i+1).padStart(2,'0')}</span><span class="module-kind">${e.folders.length?e.folders.length+' mục con':'Nhóm bài học'} ${icon('chevron')}</span></div><h3>${esc(folderLabel(f))}</h3><p>${countLine(e)}</p><div class="module-progress"><div class="progress-track"><span style="width:${percent}%"></span></div><small>${!e.videos.length?'Tài liệu tham khảo':completed?`${completed}/${e.videos.length} video đã học`:'Chưa bắt đầu'}</small></div></a>`}
  function courseDetail(id,folderId){const c=courses.find(c=>c.id===id);if(!c)return empty('Không tìm thấy khóa học','Quay lại thư viện để chọn khóa học.','book',button('Mở thư viện','data-nav="library"'));const trail=folderTrail(index,c.id,folderId||c.id),folder=trail.at(-1),entry=index.folders.get(folder.id);if(current?.folder.id!==folder.id){query='';type='all';status='all';page=1;includeChildren=entry.folders.length>0;}current={c,folder,entry,trail};const g=groupFor(c.id),isRoot=folder.id===c.id,last=entry.videos.find(v=>v.id===progress().last),next=last||entry.videos.find(v=>!progress().completed[v.id])||entry.videos[0],completed=done(entry);
    return `<nav class="content-breadcrumbs" aria-label="Đường dẫn khóa học"><a href="#library">Thư viện</a><span>›</span>${g?`<a href="${groupLink(g)}">${esc(g.title)}</a><span>›</span>`:''}${trail.map((f,i)=>trailLink(c.id,f.id,i===0?c.title:folderLabel(f),i===trail.length-1)).join('<span>›</span>')}</nav><div class="course-title-row"><div><div class="eyebrow">${isRoot?'TỔNG QUAN KHÓA HỌC':'CHƯƠNG & CHỦ ĐỀ'}</div><h1>${esc(isRoot?c.title:folderLabel(folder))}</h1><p class="course-description">${countLine(entry)} · ${completed} video đã hoàn thành</p><p class="fine-print" style="margin:4px 0 0">Tổng video và tài liệu bao gồm cả các mục con.</p></div>${next?button(last?'Học tiếp bài gần nhất':'Học bài chưa hoàn thành',`data-play="${next.id}"`,'btn-primary','play'):''}</div>${ctx.learningBlock?.(c.id,folder.id)||''}<div class="layout-toolbar"><button class="layout-panel-toggle" data-layout-panel="outline" aria-controls="course-outline" aria-expanded="true">${icon('back')}<span>Thu gọn mục lục</span></button></div><div class="course-layout">${sideTree(c,folder,trail)}<section class="course-content"><div class="folder-overview"><span>${icon('folder')} ${isRoot?'Bạn đang ở đầu khóa học':'Nội dung trong mục này'}</span><div><strong>${entry.folders.length}</strong> mục con <span>·</span> <strong>${completed}/${entry.videos.length}</strong> video đã học</div></div>${entry.folders.length?`<div class="section-title"><div><h2>${isRoot?'Chọn khóa nhỏ hoặc chủ đề':'Đi tiếp theo mục lục'}</h2><p>Mở từng mục để xem các chương và bài học bên trong.</p></div></div><div class="module-grid">${entry.folders.map((f,i)=>folderCard(c,f,i)).join('')}</div>`:''}<section class="folder-resources"><div class="section-title"><div><h2>${entry.folders.length?'Bài giảng & tài liệu':'Bài học trong chủ đề'}</h2><p>${entry.folders.length?'Mặc định gồm cả mục con. Bỏ chọn bên dưới để chỉ xem tệp ở cấp hiện tại.':'Video, bài tập, âm thanh và tài liệu trong cùng một mục.'}</p></div></div><div class="scope-tools"><label class="search-box">${icon('search')}<input type="search" id="folder-search" aria-label="Tìm trong mục này và các mục con" value="${esc(query)}" placeholder="Tìm bài học trong mục này và các mục con…"></label><select id="folder-status" aria-label="Trạng thái học"><option value="all">Tất cả trạng thái</option><option value="new" ${status==='new'?'selected':''}>Video chưa học</option><option value="done" ${status==='done'?'selected':''}>Video đã hoàn thành</option></select></div>${entry.folders.length?`<label class="include-children"><input id="include-children" type="checkbox" ${includeChildren?'checked':''}> Bao gồm học liệu trong các mục con (${fmt(entry.videos.length+entry.docs.length)})</label>`:''}<div id="folder-files" aria-live="polite"></div></section></section></div>`;
  }
  function fillFolder(){if(!current||!$('#folder-files'))return;const {entry,c}=current,listing=folderListing(entry,{query,includeChildren,status,type},progress().completed),list=listing.items;const limit=20,total=Math.max(1,Math.ceil(list.length/limit));page=Math.min(page,total);
    $('#folder-files').innerHTML=`<div class="tabs scope-tabs" role="tablist" aria-label="Học liệu trong mục"><button class="tab ${type==='all'?'active':''}" data-scope-type="all" role="tab" aria-selected="${type==='all'}">Tất cả (${fmt(listing.total)})</button><button class="tab ${type==='videos'?'active':''}" data-scope-type="videos" role="tab" aria-selected="${type==='videos'}">Video (${fmt(listing.videoCount)})</button><button class="tab ${type==='docs'?'active':''}" data-scope-type="docs" role="tab" aria-selected="${type==='docs'}">Tài liệu & âm thanh (${fmt(listing.documentCount)})</button></div><div class="resource-result-label"><span>${fmt(list.length)} học liệu${query.trim()?' trong kết quả tìm kiếm':includeChildren?' trong mục này và mục con':' ở cấp hiện tại'}</span><span>Thứ tự theo tên bài</span></div>${list.length?`<div class="video-list">${list.slice((page-1)*limit,page*limit).map(videoRow).join('')}</div>`:empty(query.trim()?'Chưa tìm thấy bài phù hợp':entry.folders.length?'Học liệu nằm trong các mục con':'Chưa có học liệu phù hợp',query.trim()?'Thử từ khóa khác hoặc chọn tất cả trạng thái.':entry.folders.length?'Chọn một mục ở phía trên để mở bài giảng và tài liệu bên trong.':'Thử chuyển tab hoặc đổi trạng thái lọc.','folder')}${total>1?`<div class="pagination">${button('Trang trước',`data-scope-page="${page-1}" ${page===1?'disabled':''}`,'btn-secondary','back')}<span>${page} / ${total}</span>${button('Trang sau',`data-scope-page="${page+1}" ${page===total?'disabled':''}`,'btn-secondary','arrow')}</div>`:''}`;
  }
  document.addEventListener('click',event=>{const el=event.target.closest('button');if(!el)return;if(el.hasAttribute('data-category')){category=el.dataset.category;ctx.refreshLibrary(category)}else if(el.hasAttribute('data-scope-type')){type=el.dataset.scopeType;page=1;fillFolder()}else if(el.hasAttribute('data-scope-page')){page=Number(el.dataset.scopePage);fillFolder();$('#folder-files').scrollIntoView({block:'start',behavior:'instant'})}});
  document.addEventListener('input',event=>{if(event.target.id==='folder-search'){query=event.target.value;page=1;fillFolder()}});
  document.addEventListener('change',event=>{if(event.target.id==='include-children'){includeChildren=event.target.checked;page=1;fillFolder()}if(event.target.id==='folder-status'){status=event.target.value;page=1;fillFolder()}});
  return {index,homeGroups,libraryIntro,groupedCourses,courseDetail,fillFolder,url};
}
